from typing import Tuple

def fibonacci_last_18_digits(n: int) -> str:
    # We only need the last 18 digits of Fibonacci numbers, so we can store much fewer
    # elements in our array.
    if n < 2:
        return str(n)

    f_prev = 0
    f_curr = 1

    for _ in range(2, n + 1):
        f_next = f_prev + f_curr
        f_prev = f_curr
        f_curr = f_next

    # Return the last 18 digits of the Fibonacci number.
    return str(f_curr)[-18:]

def solve(n: int, a: int, d: int) -> Tuple[int, int]:
    # Iterate over possible b and e values.
    # We only need to check values of b and e that result in Fibonacci numbers with at least
    # 18 digits since we are only interested in the last 18 digits.

    for b in range(1, int(1e18)):
        for e in range(1, int(1e18)):
            valid = True
            for i in range(n):
                ai = a + i * d
                bi = b + i * e
                f_bi_last_18 = fibonacci_last_18_digits(bi)
                if str(ai) not in f_bi_last_18:
                    valid = False
                    break
            if valid:
                return b, e
    return -1

